ALTER TABLE "gym"."memberships" ADD CONSTRAINT "membership_snapshot_shape" CHECK (coalesce("gym"."memberships"."snapshot" ?& array['planId','planVersionId','planCode','planVersion','branchId','name','amountMinor','currency','durationUnit','durationCount','accessMode','gymFloor','classes','personalTraining'] and jsonb_typeof("gym"."memberships"."snapshot"->'amountMinor')='number' and jsonb_typeof("gym"."memberships"."snapshot"->'currency')='string' and ("gym"."memberships"."snapshot"->>'currency') ~ '^[A-Z]{3}$' and jsonb_typeof("gym"."memberships"."snapshot"->'planVersionId')='string' and ("gym"."memberships"."snapshot"->>'planId') ~ '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$' and ("gym"."memberships"."snapshot"->>'branchId')="gym"."memberships"."home_branch_id"::text and ("gym"."memberships"."snapshot"->>'planVersion') ~ '^[1-9][0-9]*$' and ("gym"."memberships"."snapshot"->>'planCode') ~ '^[A-Z0-9][A-Z0-9-]{0,23}$' and jsonb_typeof("gym"."memberships"."snapshot"->'name')='string' and length(btrim("gym"."memberships"."snapshot"->>'name')) between 1 and 100 and ("gym"."memberships"."snapshot"->>'accessMode') in ('home_branch','all_branches') and jsonb_typeof("gym"."memberships"."snapshot"->'gymFloor')='boolean' and jsonb_typeof("gym"."memberships"."snapshot"->'classes')='boolean' and jsonb_typeof("gym"."memberships"."snapshot"->'personalTraining')='boolean' and (("gym"."memberships"."snapshot"->>'gymFloor')::boolean or ("gym"."memberships"."snapshot"->>'classes')::boolean or ("gym"."memberships"."snapshot"->>'personalTraining')::boolean) and ((("gym"."memberships"."snapshot"->>'durationUnit')='months' and ("gym"."memberships"."snapshot"->>'durationCount')::int between 1 and 120) or (("gym"."memberships"."snapshot"->>'durationUnit')='days' and ("gym"."memberships"."snapshot"->>'durationCount')::int between 1 and 3650)),false));